rules_version = '2';
service cloud.firestore {
 match /databases/{database}/documents {
  match /books/{bookId} {
   allow read: if true;
   allow create, update: if request.resource.data.keys().hasOnly(['title','pages']) && request.resource.data.title is string && request.resource.data.pages is int && request.resource.data.pages > 0;
   allow delete: if false;
  }
 }
}
